-- S1: start date from the semester start UPDATE course SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME) WHERE start_date IS NULL AND semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME) < end_date); UPDATE course SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME) WHERE start_date IS NULL AND semester REGEXP '^SS[0-9]{2}$' AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME) < end_date);
-- S2: end date from the semester end UPDATE course SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME) WHERE end_date IS NULL AND semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME) > start_date); UPDATE course SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME) WHERE end_date IS NULL AND semester REGEXP '^SS[0-9]{2}$' AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME) > start_date);
-- S3: start date from the earliest date in the course content. COALESCE to a far future sentinel and NULLIF -- back, because MySQL LEAST returns NULL as soon as one argument is NULL while PostgreSQL and H2 skip NULLs. -- The sentinel keeps all three engines on the same result. UPDATE course SET start_date = NULLIF(LEAST( COALESCE((SELECT MIN(e.release_date) FROM exercise e WHERE e.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(e.start_date) FROM exercise e WHERE e.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(l.start_date) FROM lecture l WHERE l.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(x.visible_date) FROM exam x WHERE x.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)) ), CAST('9999-12-31 00:00:00' AS DATETIME)) WHERE start_date IS NULL AND (end_date IS NULL OR NULLIF(LEAST( COALESCE((SELECT MIN(e.release_date) FROM exercise e WHERE e.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(e.start_date) FROM exercise e WHERE e.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(l.start_date) FROM lecture l WHERE l.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT MIN(x.visible_date) FROM exam x WHERE x.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)) ), CAST('9999-12-31 00:00:00' AS DATETIME)) < end_date);
-- S4: end date from the latest date in the course content UPDATE course SET end_date = NULLIF(GREATEST( COALESCE((SELECT MAX(e.due_date) FROM exercise e WHERE e.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(e.assessment_due_date) FROM exercise e WHERE e.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(l.end_date) FROM lecture l WHERE l.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(x.end_date) FROM exam x WHERE x.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)) ), CAST('1000-01-01 00:00:00' AS DATETIME)) WHERE end_date IS NULL AND (start_date IS NULL OR NULLIF(GREATEST( COALESCE((SELECT MAX(e.due_date) FROM exercise e WHERE e.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(e.assessment_due_date) FROM exercise e WHERE e.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(l.end_date) FROM lecture l WHERE l.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT MAX(x.end_date) FROM exam x WHERE x.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)) ), CAST('1000-01-01 00:00:00' AS DATETIME)) > start_date);
-- S5 and S6: derive the missing bound from the one that is set UPDATE course SET start_date = DATE_SUB(end_date, INTERVAL 6 MONTH) WHERE start_date IS NULL AND end_date IS NOT NULL; UPDATE course SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL AND start_date IS NOT NULL;
-- S7 and S8: last resort for a course with no temporal information at all UPDATE course SET start_date = NOW(3) WHERE start_date IS NULL; UPDATE course SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL;
-- S9: semester from the start date UPDATE course SET semester = CASE WHEN MONTH(start_date) >= 10 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2000, 2, '0'), '/', LPAD(YEAR(start_date) - 1999, 2, '0')) WHEN MONTH(start_date) <= 3 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2001, 2, '0'), '/', LPAD(YEAR(start_date) - 2000, 2, '0')) ELSE CONCAT('SS', LPAD(YEAR(start_date) - 2000, 2, '0')) END WHERE semester IS NULL OR semester = '';

